const $=id=>document.getElementById(id),loginView=$("loginView"),appView=$("appView");
$("apiUrl").value=state.apiBase;

async function api(path,options={}){const base=state.apiBase.replace(/\/$/,"");const headers={...(options.headers||{})};if(options.body&&!(options.body instanceof FormData)&&!headers["Content-Type"])headers["Content-Type"]="application/json";if(state.token)headers.Authorization=`Bearer ${state.token}`;const r=await fetch(base+path,{...options,headers});if(r.status===401&&path!=="/api/auth/login"){logout();throw new Error("Session expired")}const text=await r.text();let data=null;try{data=text?JSON.parse(text):null}catch{data=text}if(!r.ok)throw new Error(data?.detail||data||`HTTP ${r.status}`);return data}
function esc(v){return String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function toast(message,type="info",timeout=3200){const root=$("toastStack");if(!root)return;const el=document.createElement("div");el.className=`toast ${type}`;el.textContent=message;root.appendChild(el);setTimeout(()=>el.remove(),timeout)}
function showLogin(message=""){appView.classList.add("hidden");loginView.classList.remove("hidden");$("loginError").textContent=message}function showApp(){loginView.classList.add("hidden");appView.classList.remove("hidden");$("userBadge").textContent=`${state.user?.name||state.user?.email||"Reviewer"} · ${state.user?.role||""}`}function logout(){state.token="";state.user=null;localStorage.removeItem("pla_token");localStorage.removeItem("pla_user");showLogin()}$("logoutBtn").onclick=logout;
$("loginBtn").onclick=async()=>{state.apiBase=$("apiUrl").value.trim().replace(/\/$/,"");localStorage.setItem("pla_api_base",state.apiBase);try{const r=await api("/api/auth/login",{method:"POST",body:JSON.stringify({email:$("email").value.trim(),password:$("password").value})});state.token=r.token;state.user=r.user;localStorage.setItem("pla_token",state.token);localStorage.setItem("pla_user",JSON.stringify(state.user));showApp();await bootstrap()}catch(e){$("loginError").textContent=e.message}};

function initViewer(){if(state.viewer)return;const v=new Potree.Viewer($("potree_render_area"));v.setEDLEnabled(true);v.setFOV(60);v.setPointBudget(2200000);v.setBackground("gradient");state.viewer=v;state.overlay=new THREE.Group();state.relation=new THREE.Group();v.scene.scene.add(state.overlay);v.scene.scene.add(state.relation)}
function initProductionViewer(){if(state.productionViewer)return;const v=new Potree.Viewer($("production_render_area"));v.setEDLEnabled(true);v.setFOV(60);v.setPointBudget(2200000);v.setBackground("gradient");state.productionViewer=v;installProductionNavigation(v)}
function can(permission){return state.permissions.has(permission)}
function renderRuntime(){const r=state.runtime||{};const env=(r.railway_environment||r.app_env||"local").toUpperCase();const version=String(r.version||"3.4").replace(/-operational$/,""),badge=$("runtimeBadge");if(badge){badge.textContent=`v${version.replace(/^v/,"")} · ${env}`;badge.className=`version env-${env.toLowerCase()}`}document.title=`JSAN InfraVerify · ${env}`}
function applyWorkspace(){const available=state.workspaces.length;$("workspaceSwitch").classList.toggle("hidden",available<2);for(const name of ["PRODUCTION","DELIVERY","QC"]){const id=name.toLowerCase()+"WorkspaceBtn";$(id)?.classList.toggle("active",state.workspace===name)}$("productionWorkspace").classList.toggle("hidden",state.workspace!=="PRODUCTION");$("deliveryWorkspace").classList.toggle("hidden",state.workspace!=="DELIVERY");$("qcWorkspace").classList.toggle("hidden",state.workspace!=="QC");$("qcKpis").classList.toggle("hidden",state.workspace!=="QC");$("productionUploadBtn").classList.toggle("hidden",!can("project.create"));$("newDatasetBtn").classList.toggle("hidden",state.workspace==="PRODUCTION"||!can("project.create"));$("reprocessBtn").classList.toggle("hidden",state.workspace==="PRODUCTION"||!can("processing.run"));if(state.workspace==="PRODUCTION"){initProductionViewer();if(state.projectId)loadProduction()}else if(state.workspace==="DELIVERY"&&state.projectId)loadWorkflow()}
function chooseWorkspace(){if(!state.workspaces.includes(state.workspace))state.workspace=state.workspaces.includes("PRODUCTION")?"PRODUCTION":(state.workspaces.includes("DELIVERY")?"DELIVERY":"QC");localStorage.setItem("pla_workspace",state.workspace);applyWorkspace()}
$("productionWorkspaceBtn").onclick=()=>{state.workspace="PRODUCTION";localStorage.setItem("pla_workspace","PRODUCTION");applyWorkspace()};
$("deliveryWorkspaceBtn").onclick=()=>{state.workspace="DELIVERY";localStorage.setItem("pla_workspace","DELIVERY");applyWorkspace()};
$("qcWorkspaceBtn").onclick=()=>{state.workspace="QC";localStorage.setItem("pla_workspace","QC");applyWorkspace()};
async function bootstrap(){const [runtime,access,projects]=await Promise.all([api("/api/system/info"),api("/api/workspaces"),api("/api/projects")]);state.runtime=runtime;state.workspaces=access.workspaces||[];state.permissions=new Set(access.permissions||[]);state.projects=projects;renderRuntime();chooseWorkspace();if(state.workspaces.includes("QC"))initViewer();renderProjectSelect();if(!state.projects.length){clearProject();if(can("project.create"))(state.workspace==="PRODUCTION"?$("productionUploadDialog"):$("uploadDialog")).showModal();return}if(!state.projectId||!state.projects.some(p=>p.id===state.projectId))state.projectId=state.projects[0].id;$("projectSelect").value=state.projectId;localStorage.setItem("pla_project_id",state.projectId);await loadProject()}
function currentProject(){return state.projects.find(p=>p.id===state.projectId)||{units:"project units"}}
function renderProjectSelect(){const s=$("projectSelect");s.innerHTML="";for(const p of state.projects){const o=document.createElement("option");o.value=p.id;o.textContent=`${p.name} · ${p.status}`;s.appendChild(o)}}
$("projectSelect").onchange=async()=>{state.projectId=$("projectSelect").value;localStorage.setItem("pla_project_id",state.projectId);state.currentPole=null;state.analysis=null;state.section=null;await loadProject()};
function clearProject(){state.poles=[];state.summary={poles:0,fail:0,review:0,unverifiable:0,open_findings:0};renderSummary();renderPoles();clearClouds();clearThreeGroup(state.overlay);clearThreeGroup(state.relation);$("viewerTitle").textContent="Upload a dataset";$("viewerSub").textContent="COLLECTION workbook + LAS/LAZ/COPC";clearCanvases()}
// QC on Production LiDAR: offer a one-click run when a dataset was imported in Production but never QC-processed.
// A Production dataset is QC-checked in a linked QC dataset that shares its LiDAR but uses its own QC Excel.
function renderQcProductionBanner(){const el=$("qcProductionBanner"),s=state.summary||{},canRun=can("processing.run"),files=`${s.lidar_blocks} LiDAR file${s.lidar_blocks===1?"":"s"}`;let html="",action=null;
  if(s.qc_job_id){html='<div><b>QC is running on the shared Production LiDAR</b><small id="qcProductionProgress">Starting…</small></div>'}
  else if(s.production_dataset&&s.qc_dataset){html=`<div><b>This is a Production dataset. Its QC runs in “${esc(s.qc_dataset.name)}”.</b><small>That QC dataset checks its own QC Excel against this dataset's LiDAR.</small></div><button type="button" id="qcBannerAction" class="primary">Open QC dataset</button>`;action=()=>openProjectInQc(s.qc_dataset.id)}
  else if(s.production_dataset&&s.lidar_blocks){html=`<div><b>This dataset's LiDAR was imported in Production. QC hasn't run yet.</b><small>${files} · upload a QC Excel to check · no LiDAR upload needed</small></div>${canRun?'<button type="button" id="qcBannerAction" class="primary">Run QC now</button>':'<small class="qc-banner-note">Ask a manager to run QC for this dataset.</small>'}`;action=()=>openQcRunDialog({sourceId:state.projectId,sourceName:currentProject().name,hasGeojson:s.has_geojson})}
  else if(s.source_project&&!s.qc_runs){html=`<div><b>QC dataset for “${esc(s.source_project.name)}”</b><small>${files} shared from Production · ${s.has_workbook?"QC Excel uploaded":"upload the QC Excel to check"}</small></div>${canRun?`<button type="button" id="qcBannerAction" class="primary">${s.has_workbook?"Run QC now":"Upload QC Excel"}</button>`:'<small class="qc-banner-note">Ask a manager to run QC for this dataset.</small>'}`;action=s.has_workbook?runQcOnProductionLidar:()=>openQcRunDialog({qcId:state.projectId,sourceName:s.source_project.name})}
  if(!html){el.classList.add("hidden");el.innerHTML="";return}
  el.innerHTML=html;el.classList.remove("hidden");if(s.qc_job_id){watchQcProductionJob(s.qc_job_id);return}if(action)$("qcBannerAction")?.addEventListener("click",action)}
function openProjectInQc(projectId){const select=$("projectSelect");select.value=projectId;select.dispatchEvent(new Event("change"))}
function setDialogProgress(prefix,p,msg){$(`${prefix}Progress`).classList.remove("hidden");$(`${prefix}Bar`).style.width=`${Math.max(0,Math.min(100,p))}%`;$(`${prefix}Message`).textContent=msg}
function openQcRunDialog(target){state.qcRunTarget=target;$("qcRunForm").reset();$("qcRunDataset").textContent=target.sourceName||"this dataset";$("qcRunGeojsonLabel").classList.toggle("hidden",!target.hasGeojson||Boolean(target.qcId));$("qcRunProgress").classList.add("hidden");$("qcRunError").textContent="";$("qcRunDialog").showModal()}
$("cancelQcRun").onclick=()=>$("qcRunDialog").close();
$("qcRunForm").onsubmit=async ev=>{ev.preventDefault();$("qcRunError").textContent="";const report=(p,m)=>setDialogProgress("qcRun",p,m),target=state.qcRunTarget||{};try{const file=$("qcRunExcel").files[0];if(!file)throw new Error("Select the QC Excel");let qcId=target.qcId;if(!qcId){report(5,"Creating the QC dataset on the shared LiDAR…");qcId=(await api(`/api/projects/${target.sourceId}/qc-dataset`,{method:"POST",body:JSON.stringify({include_geojson:$("qcRunGeojson").checked})})).id}await sendFile(qcId,file,"WORKBOOK",0,1,report);report(70,"Starting QC…");await api(`/api/projects/${qcId}/process`,{method:"POST"});report(100,"QC started");$("qcRunDialog").close();state.projectId=qcId;localStorage.setItem("pla_project_id",qcId);await bootstrap();toast("QC started on the shared Production LiDAR.","success")}catch(e){$("qcRunError").textContent=e.message;report(0,"QC not started")}};
async function runQcOnProductionLidar(){const btn=$("qcBannerAction");btn.disabled=true;btn.textContent="Starting…";try{const queued=await api(`/api/projects/${state.projectId}/process`,{method:"POST"});state.summary={...state.summary,qc_runs:(state.summary?.qc_runs||0)+1,qc_job_id:queued.job_id};renderQcProductionBanner()}catch(e){toast(e.message,"error",5200);btn.disabled=false;btn.textContent="Run QC now"}}
async function watchQcProductionJob(jobId){if(state.qcProductionWatch===jobId)return;state.qcProductionWatch=jobId;const projectId=state.projectId;let finished=false;try{for(;;){await new Promise(r=>setTimeout(r,2000));if(state.projectId!==projectId||state.qcProductionWatch!==jobId)return;const job=await api(`/api/jobs/${jobId}`);const progress=$("qcProductionProgress");if(progress)progress.textContent=`${job.progress}% · ${job.stage}`;if(job.status==="SUCCEEDED"){toast("QC finished on the Production LiDAR.","success");finished=true;break}if(job.status==="FAILED"){toast((job.error||"QC failed").split("\n")[0],"error",6500);finished=true;break}}}catch(e){toast(e.message,"error",5200)}finally{if(state.qcProductionWatch===jobId)state.qcProductionWatch=null}if(finished&&state.projectId===projectId&&state.workspace==="QC")await loadProject()}
async function loadProject(){if(state.workspace==="PRODUCTION"){await loadProduction();return}try{const [summary,poles]=await Promise.all([api(`/api/projects/${state.projectId}/summary`),api(`/api/projects/${state.projectId}/poles`)]);state.summary=summary;state.poles=poles;renderSummary();renderPoles();renderQcProductionBanner();await loadWorkflow();if(summary.project_status==="PROCESSING"||summary.project_status==="UPLOADING"){$("viewerTitle").textContent="Dataset is not ready yet";$("viewerSub").textContent=summary.project_status}else if(!poles.length){$("viewerTitle").textContent="No processed poles";$("viewerSub").textContent="Upload/process the dataset or inspect its job status"}}catch(e){toast(e.message,"error",5200)}}
async function loadWorkflow(){if(!state.projectId)return;try{state.workflow=await api(`/api/projects/${state.projectId}/workflow`);renderWorkflow()}catch(e){state.workflow=null;if(state.workspace==="DELIVERY")toast(e.message,"error",4200)}}
function renderWorkflow(){const w=state.workflow||{},v=w.current_version||{};$("deliveryVersion").textContent=v.version_no?`v${v.version_no}`:"—";$("deliveryStatus").textContent=v.status||"No version";const cmp=w.comparison||{};$("deliveryComparison").innerHTML=`<b>NEW ${cmp.NEW??0}</b><b>STILL OPEN ${cmp.STILL_OPEN??0}</b><b>RESOLVED ${cmp.RESOLVED??0}</b>`;$("deliveryVersions").innerHTML=(w.versions||[]).map(x=>`<div class="workflow-row"><span><b>v${x.version_no}</b><small>${esc(x.created_by||"system")}</small></span><span class="workflow-status">${esc(x.status)}</span></div>`).join("")||'<div class="empty-workflow">No versions yet.</div>';$("deliveryCorrections").innerHTML=(w.corrections||[]).map(x=>`<div class="workflow-row correction-row"><span><b>${esc(x.finding_id)}</b><small>${esc(x.comment||"Correction requested")}</small></span><span><em class="workflow-status">${esc(x.status)}</em>${x.status==="OPEN"&&can("correction.resolve")?`<button class="resolve-correction" data-id="${esc(x.id)}">Resolve</button>`:""}</span></div>`).join("")||'<div class="empty-workflow">No correction requests.</div>';document.querySelectorAll(".resolve-correction").forEach(b=>b.onclick=async()=>{try{await api(`/api/corrections/${b.dataset.id}/resolve`,{method:"POST"});await loadWorkflow();toast("Correction resolved.","success")}catch(e){toast(e.message,"error")}});$("newRevisionBtn").classList.toggle("hidden",!can("version.create"));$("approveVersionBtn").classList.toggle("hidden",!can("version.approve")||v.status==="APPROVED")}
$("newRevisionBtn").onclick=async()=>{if(!state.projectId)return;try{const v=await api(`/api/projects/${state.projectId}/versions`,{method:"POST"});state.uploadRevisionProjectId=state.projectId;const p=currentProject();$("uploadForm").reset();$("datasetName").value=p.name||"";$("datasetCustomer").value=p.customer||"PLA";$("datasetCrs").value=p.crs||"EPSG:6424";$("datasetUnits").value=p.units||"US survey foot";["datasetName","datasetCustomer","datasetCrs","datasetUnits"].forEach(id=>$(id).disabled=true);$("uploadProgress").classList.add("hidden");$("uploadError").textContent="";$("uploadDialog").querySelector("h2").textContent=`Upload revision v${v.version_no}`;$("uploadDialog").showModal();await loadWorkflow()}catch(e){toast(e.message,"error",5200)}};
$("approveVersionBtn").onclick=async()=>{const v=state.workflow?.current_version;if(!v)return;try{await api(`/api/projects/${state.projectId}/versions/${v.id}/approve`,{method:"POST"});await loadProject();toast(`Version v${v.version_no} approved.`,"success")}catch(e){toast(e.message,"error",5200)}};
function renderSummary(){const s=state.summary||{};$("kpiPoles").textContent=s.poles??0;$("kpiFail").textContent=s.fail??0;$("kpiReview").textContent=s.review??0;$("kpiUnver").textContent=s.unverifiable??0;$("kpiOpen").textContent=s.open_findings??0;$("kpiCurrent").textContent=state.currentPole?`P${state.currentPole.internal_id}`:"—"}
function renderPoles(){const q=$("poleSearch").value.trim().toLowerCase(),root=$("poleList");root.innerHTML="";for(const p of state.poles.filter(p=>!q||String(p.internal_id).includes(q)||String(p.pole_number||"").toLowerCase().includes(q))){const row=document.createElement("div");row.className="pole-row"+(state.currentPole?.internal_id===p.internal_id?" active":"");row.innerHTML=`<div class="pole-id">${p.internal_id}</div><div class="pole-meta"><b>${esc(p.pole_number||"No tag")}</b><small>${esc(p.block_name||"No LiDAR block")}</small></div><span class="status-chip ${p.qc_status}">${p.qc_status}</span>`;row.onclick=()=>selectPole(p.internal_id);root.appendChild(row)}}$("poleSearch").oninput=renderPoles;
function fillTargetSelect(defaultId){const s=$("targetPole");s.innerHTML='<option value="">Auto</option>';for(const p of state.poles){if(p.internal_id===state.currentPole?.internal_id)continue;const o=document.createElement("option");o.value=p.internal_id;o.textContent=`P${p.internal_id} · ${p.pole_number||"No tag"}`;s.appendChild(o)}if(defaultId)s.value=String(defaultId)}

async function selectPole(id){const pole=state.poles.find(x=>x.internal_id===Number(id));if(!pole)return;state.currentPole=pole;state.section=null;state.analysis=null;renderPoles();renderSummary();$("viewerEmpty").classList.add("hidden");$("loading").classList.remove("hidden");$("viewerTitle").textContent=`Pole ${pole.internal_id} · ${pole.pole_number||"No tag"}`;$("viewerSub").textContent=`${pole.block_name||"No LiDAR"} · ${pole.qc_status} · ${currentProject().units}`;$("sectionStatus").textContent="Loading pole evidence…";try{
const scene=await api(`/api/projects/${state.projectId}/poles/${pole.internal_id}/scene?include_related=true`);
state.currentScene=scene;renderPoleSummary(scene);renderFindings(scene.findings);renderRelatedButton(scene);await renderScene(scene);
try{
const analysis=await api(`/api/projects/${state.projectId}/poles/${pole.internal_id}/analysis-frame`);
state.analysis=analysis;fillTargetSelect(analysis.frame.target_internal_id);state.crossStation=0;configureCrossSlider();renderAnalysisViews();
const mode=analysis.frame.primary_has_3d===false?"source/pre-pop XY":"delivery 3D";
$("sectionStatus").textContent=`Analysis frame ready · located from ${mode}`;
await prepareSection();
}catch(ae){
state.analysis=null;clearCanvases();fillTargetSelect(null);$("sectionStatus").textContent=`Profile unavailable: ${ae.message}`;
if(!(scene.blocks||[]).length){$("viewerEmpty").classList.remove("hidden");$("viewerEmpty").innerHTML=`<div class="empty-icon">!</div><h3>Location evidence unavailable</h3><p>${esc(ae.message)}</p>`}
}
}catch(e){state.analysis=null;state.currentScene=null;clearCanvases();$("viewerEmpty").classList.remove("hidden");$("viewerEmpty").innerHTML=`<div class="empty-icon">!</div><h3>Evidence could not load</h3><p>${esc(e.message)}</p>`;$("sectionStatus").textContent=e.message}finally{$("loading").classList.add("hidden")}}
async function reloadAnalysisAndSection(){if(!state.currentPole)return;const target=$("targetPole").value?Number($("targetPole").value):null;try{$("sectionStatus").textContent="Updating profile axis…";state.analysis=await api(`/api/projects/${state.projectId}/poles/${state.currentPole.internal_id}/analysis-frame${target?`?target_internal_id=${target}`:""}`);fillTargetSelect(state.analysis.frame.target_internal_id);state.section=null;state.crossStation=0;configureCrossSlider();renderAnalysisViews();await prepareSection()}catch(e){$("sectionStatus").textContent=e.message}}
$("targetPole").onchange=reloadAnalysisAndSection;$("refreshProfile").onclick=reloadAnalysisAndSection;
function configureCrossSlider(){const len=Math.max(1,Number(state.analysis?.frame?.length||1));const s=$("crossStation");s.min=0;s.max=String(len);s.step=String(Math.max(.25,len/200));s.value=String(Math.min(state.crossStation,len));updateCrossLabel()}
$("crossStation").oninput=()=>{state.crossStation=Number($("crossStation").value);updateCrossLabel();renderAnalysisViews()};
function updateCrossLabel(){const u=currentProject().units||"units";$("crossStationValue").textContent=`${state.crossStation.toFixed(1)} ${u}`;$("crossLabel").textContent=`Station ${state.crossStation.toFixed(1)} ${u}`}

function renderPoleSummary(scene){const p=scene.pole,box=$("poleSummary"),incomplete=p.bottom_elev_ft==null||p.top_elev_ft==null;box.classList.remove("hidden");box.innerHTML=`<b>Pole ${p.internal_id} · ${esc(p.pole_number||"No tag")}</b><div class="grid"><div class="kv"><span>Status</span><b>${p.qc_status}</b></div><div class="kv"><span>LiDAR block</span><b>${esc(p.block_name||"—")}</b></div><div class="kv"><span>Bottom elevation</span><b>${p.bottom_elev_ft??"—"}</b></div><div class="kv"><span>Top elevation</span><b>${p.top_elev_ft??"—"}</b></div><div class="kv"><span>Fail</span><b>${p.qc_fail}</b></div><div class="kv"><span>Review</span><b>${p.qc_review}</b></div></div>${incomplete&&p.block_name?`<div style="margin-top:8px;color:#7fd3ff">LiDAR located from workbook XY; complete delivery 3D geometry is not yet available.</div>`:""}${p.remarks?`<div style="margin-top:8px;color:#ffcf7d">${esc(p.remarks)}</div>`:""}`}
function renderFindings(findings){const rows=findings.filter(f=>!state.severity||f.severity===state.severity);$("findingCount").textContent=`${rows.length} finding${rows.length===1?"":"s"}`;const root=$("findingList");root.innerHTML="";if(!rows.length){root.innerHTML='<div style="padding:16px;color:#98adb8">No findings for this filter.</div>';return}for(const f of rows){const d=document.createElement("article");d.className=`finding ${f.severity} ${f.status!=="OPEN"?"resolved":""}`;const actions=[can("finding.review")?'<button class="decision-btn review-action">Review decision</button>':"",can("correction.create")&&f.status!=="CORRECTED"?'<button class="decision-btn correction-action">Send correction</button>':""].join("");d.innerHTML=`<div class="finding-head"><span>${esc(f.rule_id)} · ${esc(f.sheet)}</span><span class="sev ${f.severity}">${f.severity}</span></div><div class="finding-msg">${esc(f.message)}</div><div class="evidence"><div><span>Delivered</span><b>${esc(f.actual??"—")}</b></div><div><span>Expected</span><b>${esc(f.expected??"—")}</b></div></div><div class="finding-foot"><span>${esc(f.field)} · ${esc(f.status)}</span><span class="finding-actions">${actions}</span></div>`;d.onclick=ev=>{if(ev.target.tagName!=="BUTTON")focusFinding(f)};d.querySelector(".review-action")?.addEventListener("click",ev=>{ev.stopPropagation();openDecision(f)});d.querySelector(".correction-action")?.addEventListener("click",async ev=>{ev.stopPropagation();const comment=prompt("Correction instruction for Delivery:",f.message)||"";try{await api(`/api/findings/${f.id}/correction`,{method:"POST",body:JSON.stringify({comment})});await loadWorkflow();toast("Sent to Delivery correction queue.","success")}catch(e){toast(e.message,"error",5200)}});root.appendChild(d)}}
$("severityFilter").onchange=()=>{state.severity=$("severityFilter").value;if(state.currentScene)renderFindings(state.currentScene.findings)};
function openDecision(f){$("decisionTitle").textContent=`${f.rule_id} · Pole ${f.internal_id}`;$("decisionFindingId").value=f.id;$("decisionComment").value="";$("decisionDialog").showModal()}$("decisionForm").onsubmit=async ev=>{if(ev.submitter?.value==="cancel")return;ev.preventDefault();try{await api(`/api/findings/${$("decisionFindingId").value}/decision`,{method:"POST",body:JSON.stringify({decision:$("decisionValue").value,comment:$("decisionComment").value||null})});$("decisionDialog").close();await loadProject();if(state.currentPole)await selectPole(state.currentPole.internal_id)}catch(e){alert(e.message)}};
function renderRelatedButton(scene){const b=$("relatedBtn");if(scene.related_poles?.length){b.classList.remove("hidden");b.textContent=`Focus span: ${scene.related_poles.map(x=>"P"+x).join(", ")}`}else b.classList.add("hidden")}$("relatedBtn").onclick=()=>focusAllEvidence();$("focusBtn").onclick=()=>focusPrimary();
async function focusFinding(f){if(f.related_poles?.length){$("targetPole").value=String(f.related_poles[0]);await reloadAnalysisAndSection();focusAllEvidence()}else focusPrimary()}

function clearThreeGroup(g){if(!g)return;while(g.children.length){const x=g.children.pop();x.geometry?.dispose?.();if(x.material){if(Array.isArray(x.material))x.material.forEach(m=>m.dispose?.());else x.material.dispose?.()}}}
function clearClouds(){if(!state.viewer)return;const scene=state.viewer.scene;const pcs=[...(scene.pointclouds||[])];for(const pc of pcs){try{const i=scene.pointclouds?.indexOf(pc)??-1;if(i>=0)scene.pointclouds.splice(i,1);scene.scenePointCloud?.remove?.(pc);scene.scene?.remove?.(pc);scene.dispatchEvent?.({type:"pointcloud_removed",pointcloud:pc})}catch(err){console.warn("Point cloud cleanup warning",err)}}state.pointclouds=[]}
function addCylinder(group,a,b,r,color,opacity=1){const p1=new THREE.Vector3(...a),p2=new THREE.Vector3(...b),dir=new THREE.Vector3().subVectors(p2,p1),len=dir.length();if(!Number.isFinite(len)||len<=0)return;const mesh=new THREE.Mesh(new THREE.CylinderGeometry(r,r,len,10),new THREE.MeshBasicMaterial({color,transparent:opacity<1,opacity,depthTest:false}));mesh.position.copy(p1).add(p2).multiplyScalar(.5);mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),dir.clone().normalize());mesh.renderOrder=900;group.add(mesh)}function addSphere(group,c,r,color){const m=new THREE.Mesh(new THREE.SphereGeometry(r,12,9),new THREE.MeshBasicMaterial({color,depthTest:false}));m.position.set(...c);m.renderOrder=905;group.add(m)}
function featureHex(t,cat){if(t==="pole")return "#ffe066";if(t==="attachment")return cat==="comm"?"#46d9ff":"#49a5ff";if(t==="equipment")return "#ff9f43";if(t==="anchor")return "#ff5252";if(t==="crossarm")return "#ffc857";if(t==="guy")return "#ff4fd8";return "#ffffff"}function featureColor(t,cat){return parseInt(featureHex(t,cat).slice(1),16)}
function buildOverlay(scene){clearThreeGroup(state.overlay);clearThreeGroup(state.relation);for(const f of scene.features){const t=f.properties.feature_type,g=f.geometry,c=featureColor(t,f.properties.category);if(g.type==="Point")addSphere(state.overlay,g.coordinates,t==="anchor"?.65:t==="equipment"?.5:.36,c);else if(g.type==="LineString")addCylinder(state.overlay,g.coordinates[0],g.coordinates[1],t==="pole"?.32:.16,c,.98)}const poleFeats=scene.features.filter(f=>f.properties.feature_type==="pole"),byId=new Map(poleFeats.map(f=>[Number(f.properties.internal_id),f]));for(const f of scene.findings){if(!f.related_poles?.length)continue;const a=byId.get(Number(f.internal_id));if(!a)continue;for(const rid of f.related_poles){const b=byId.get(Number(rid));if(!b)continue;addCylinder(state.relation,a.geometry.coordinates[1],b.geometry.coordinates[1],.11,f.severity==="FAIL"?0xff6b35:0xffc857,.85)}}}
function loadPointCloud(url,name){return new Promise((resolve,reject)=>{let done=false;const timer=setTimeout(()=>{if(!done){done=true;reject(new Error(`Timed out loading ${name}`))}},60000);try{Potree.loadPointCloud(url,name,e=>{if(done)return;done=true;clearTimeout(timer);state.viewer.scene.addPointCloud(e.pointcloud);const m=e.pointcloud.material;m.size=1;m.pointSizeType=Potree.PointSizeType.ADAPTIVE;m.activeAttributeName="elevation";state.pointclouds.push(e.pointcloud);resolve(e.pointcloud)})}catch(err){clearTimeout(timer);reject(err)}})}
async function renderScene(scene){clearClouds();buildOverlay(scene);applyMode();const blocks=(scene.blocks||[]).filter(b=>b.copc_url);if(!blocks.length){$("viewerSub").textContent+=" · no matching LiDAR block";focusPrimary();return}for(const b of blocks)await loadPointCloud(b.copc_url,b.name);applyMode();focusPrimary()}
function poleFeatures(){return state.currentScene?.features.filter(f=>f.properties.feature_type==="pole")||[]}function featureCenter(f){const a=f.geometry.coordinates[0],b=f.geometry.coordinates[1];return[(a[0]+b[0])/2,(a[1]+b[1])/2,(a[2]+b[2])/2]}function focusPrimary(){const f=poleFeatures().find(x=>Number(x.properties.internal_id)===Number(state.currentPole?.internal_id));if(!f){focusAllEvidence();return}const c=featureCenter(f);state.viewer.scene.view.setView([c[0]+48,c[1]-48,c[2]+30],c)}function focusAllEvidence(){const fs=poleFeatures();if(!fs.length){state.viewer.fitToScreen(.7);return}const cs=fs.map(featureCenter),min=[Math.min(...cs.map(x=>x[0])),Math.min(...cs.map(x=>x[1])),Math.min(...cs.map(x=>x[2]))],max=[Math.max(...cs.map(x=>x[0])),Math.max(...cs.map(x=>x[1])),Math.max(...cs.map(x=>x[2]))],c=[(min[0]+max[0])/2,(min[1]+max[1])/2,(min[2]+max[2])/2],span=Math.max(max[0]-min[0],max[1]-min[1],35);state.viewer.scene.view.setView([c[0]+span*.9,c[1]-span*.9,c[2]+Math.max(30,span*.45)],c)}function applyMode(){const both=state.mode==="both";state.overlay.visible=both||state.mode==="delivery";state.relation.visible=state.overlay.visible;state.pointclouds.forEach(pc=>pc.visible=both||state.mode==="lidar");document.querySelectorAll(".mode").forEach(b=>b.classList.toggle("active",b.dataset.mode===state.mode));renderAnalysisViews()}document.querySelectorAll(".mode").forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;applyMode()});

async function prepareSection(){if(!state.currentPole||!state.analysis)return;const target=state.analysis.frame.target_internal_id;const width=Number($("profileWidth").value||12),resolution=Number($("profileResolution").value||.5),depth=Math.max(8,width);$("sectionStatus").textContent="Generating LiDAR profile / cross section…";try{const prep=await api(`/api/projects/${state.projectId}/poles/${state.currentPole.internal_id}/sections/prepare`,{method:"POST",body:JSON.stringify({target_internal_id:target,width,depth,resolution,max_points:90000})});if(prep.cached){state.section=await api(`/api/projects/${state.projectId}/analysis/result?key=${encodeURIComponent(prep.result_key)}`);$("sectionStatus").textContent=`Profile ready · ${state.section.sample_count??0} sampled points`;renderAnalysisViews();return}let job;for(;;){await new Promise(r=>setTimeout(r,1200));job=await api(`/api/jobs/${prep.job_id}`);$("sectionStatus").textContent=`${job.stage} · ${job.progress}%`;if(job.status==="SUCCEEDED")break;if(job.status==="FAILED")throw new Error(job.error||"Profile extraction failed")}state.section=await api(`/api/jobs/${prep.job_id}/result`);$("sectionStatus").textContent=`Profile ready · ${state.section.sample_count??0} / ${state.section.point_count??0} corridor points`;renderAnalysisViews()}catch(e){state.section=null;$("sectionStatus").textContent=`Profile unavailable: ${e.message}`;renderAnalysisViews()}}

function canvasSetup(id){const c=$(id),dpr=Math.min(2,window.devicePixelRatio||1),rect=c.getBoundingClientRect();const w=Math.max(50,Math.floor(rect.width*dpr)),h=Math.max(50,Math.floor(rect.height*dpr));if(c.width!==w||c.height!==h){c.width=w;c.height=h}const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return{c,ctx,w:rect.width,h:rect.height}}
function range(vals,pad=.08,fallback=[0,1]){const clean=vals.filter(Number.isFinite);if(!clean.length)return fallback;let a=Math.min(...clean),b=Math.max(...clean);if(a===b){a-=1;b+=1}const d=b-a;return[a-d*pad,b+d*pad]}
function mapper(xr,yr,w,h,m=24){return{x:x=>m+(x-xr[0])/(xr[1]-xr[0])*(w-2*m),y:y=>h-m-(y-yr[0])/(yr[1]-yr[0])*(h-2*m),ix:px=>xr[0]+(px-m)/(w-2*m)*(xr[1]-xr[0])}}
function drawAxes(ctx,w,h,xr,yr,m=24){ctx.strokeStyle='#294754';ctx.lineWidth=1;ctx.strokeRect(m,m,w-2*m,h-2*m);ctx.fillStyle='#7895a3';ctx.font='9px Segoe UI';ctx.fillText(xr[0].toFixed(1),m,h-7);ctx.textAlign='right';ctx.fillText(xr[1].toFixed(1),w-m,h-7);ctx.textAlign='left';ctx.fillText(yr[1].toFixed(1),3,m+3);ctx.fillText(yr[0].toFixed(1),3,h-m)}
function lidarColor(z,zr){const t=Math.max(0,Math.min(1,(z-zr[0])/Math.max(.001,zr[1]-zr[0])));const hue=210-190*t;return`hsl(${hue} 78% 62%)`}
function projectedFeatures(){return state.analysis?.features||[]}
function lidarPoints(){return state.section?.points||[]}
function drawFeatures(ctx,map,mode){if(state.mode==="lidar")return;for(const f of projectedFeatures()){const g=f.geometry,ft=f.properties.feature_type,col=featureHex(ft,f.properties.category);ctx.strokeStyle=col;ctx.fillStyle=col;ctx.lineWidth=ft==="pole"?2.5:1.5;if(g.type==="Point"){const p=g[mode];if(!p)continue;ctx.beginPath();ctx.arc(map.x(p[0]),map.y(p[1]),ft==="anchor"?4:3,0,Math.PI*2);ctx.fill()}else if(g.type==="LineString"){const pts=g[mode]||[];if(!pts.length)continue;ctx.beginPath();ctx.moveTo(map.x(pts[0][0]),map.y(pts[0][1]));for(const p of pts.slice(1))ctx.lineTo(map.x(p[0]),map.y(p[1]));ctx.stroke()}}}
function renderPlan(){const{c,ctx,w,h}=canvasSetup('planCanvas');ctx.clearRect(0,0,w,h);ctx.fillStyle='#071219';ctx.fillRect(0,0,w,h);if(!state.analysis){return}const pts=lidarPoints(),fs=projectedFeatures();const xs=[...pts.map(p=>p.station),...fs.flatMap(f=>f.geometry.type==='Point'?[f.geometry.plan[0]]:f.geometry.plan.map(p=>p[0]))],ys=[...pts.map(p=>p.offset),...fs.flatMap(f=>f.geometry.type==='Point'?[f.geometry.plan[1]]:f.geometry.plan.map(p=>p[1]))];const xr=range(xs,.08,[-10,Math.max(10,state.analysis.frame.length+10)]),yr=range(ys,.15,[-10,10]),map=mapper(xr,yr,w,h);state.canvasRanges.plan={xr,yr,map,w,h};drawAxes(ctx,w,h,xr,yr);if(state.mode!=="delivery"&&pts.length){ctx.globalAlpha=.5;ctx.fillStyle='#5ec8ef';for(const p of pts){ctx.fillRect(map.x(p.station),map.y(p.offset),1.2,1.2)}ctx.globalAlpha=1}drawFeatures(ctx,map,'plan');ctx.strokeStyle='#fff';ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(map.x(state.crossStation),24);ctx.lineTo(map.x(state.crossStation),h-24);ctx.stroke();ctx.setLineDash([]);$("planNote").style.display='none'}
function renderProfile(){const{c,ctx,w,h}=canvasSetup('profileCanvas');ctx.clearRect(0,0,w,h);ctx.fillStyle='#071219';ctx.fillRect(0,0,w,h);if(!state.analysis)return;const pts=lidarPoints(),fs=projectedFeatures();const xs=[...pts.map(p=>p.station),...fs.flatMap(f=>f.geometry.type==='Point'?[f.geometry.profile[0]]:f.geometry.profile.map(p=>p[0]))],zs=[...pts.map(p=>p.z),...fs.flatMap(f=>f.geometry.type==='Point'?[f.geometry.profile[1]]:f.geometry.profile.map(p=>p[1]))];const xr=range(xs,.06,[-10,Math.max(10,state.analysis.frame.length+10)]),zr=range(zs,.08,[0,100]),map=mapper(xr,zr,w,h);state.canvasRanges.profile={xr,yr:zr,map,w,h};drawAxes(ctx,w,h,xr,zr);if(state.mode!=="delivery"&&pts.length){ctx.globalAlpha=.7;for(const p of pts){ctx.fillStyle=lidarColor(p.z,zr);ctx.fillRect(map.x(p.station),map.y(p.z),1.4,1.4)}ctx.globalAlpha=1}drawFeatures(ctx,map,'profile');ctx.strokeStyle='#fff';ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(map.x(state.crossStation),24);ctx.lineTo(map.x(state.crossStation),h-24);ctx.stroke();ctx.setLineDash([]);$("profileNote").style.display=pts.length?'none':'block'}
function renderCross(){const{c,ctx,w,h}=canvasSetup('crossCanvas');ctx.clearRect(0,0,w,h);ctx.fillStyle='#071219';ctx.fillRect(0,0,w,h);if(!state.analysis)return;const all=lidarPoints(),depth=Number(state.section?.settings?.cross_depth||12),pts=all.filter(p=>Math.abs(p.station-state.crossStation)<=depth/2),fs=projectedFeatures();const offsets=[...pts.map(p=>p.offset),...fs.flatMap(f=>f.geometry.type==='Point'?[f.geometry.cross[0]]:f.geometry.cross.map(p=>p[0]))],zs=[...pts.map(p=>p.z),...fs.flatMap(f=>f.geometry.type==='Point'?[f.geometry.cross[1]]:f.geometry.cross.map(p=>p[1]))];const xr=range(offsets,.15,[-10,10]),zr=range(zs,.08,[0,100]),map=mapper(xr,zr,w,h);drawAxes(ctx,w,h,xr,zr);if(state.mode!=="delivery"&&pts.length){ctx.globalAlpha=.75;for(const p of pts){ctx.fillStyle=lidarColor(p.z,zr);ctx.fillRect(map.x(p.offset),map.y(p.z),1.5,1.5)}ctx.globalAlpha=1}if(state.mode!=="lidar"){for(const f of fs){const geom=f.geometry,src=geom.type==='Point'?[geom.cross]:geom.cross;const orig=geom.type==='Point'?[geom.plan]:geom.plan;const near=[];for(let i=0;i<src.length;i++){const station=orig[i]?.[0]??0;if(Math.abs(station-state.crossStation)<=depth/2)near.push(src[i])}if(!near.length)continue;ctx.strokeStyle=featureHex(f.properties.feature_type,f.properties.category);ctx.fillStyle=ctx.strokeStyle;ctx.lineWidth=2;if(geom.type==='Point'){ctx.beginPath();ctx.arc(map.x(near[0][0]),map.y(near[0][1]),3,0,Math.PI*2);ctx.fill()}else{ctx.beginPath();ctx.moveTo(map.x(near[0][0]),map.y(near[0][1]));for(const p of near.slice(1))ctx.lineTo(map.x(p[0]),map.y(p[1]));ctx.stroke()}}}$("crossNote").style.display=pts.length?'none':'block'}
function renderAnalysisViews(){renderPlan();renderProfile();renderCross()}
function clearCanvases(){for(const id of ['planCanvas','profileCanvas','crossCanvas']){const c=$(id);if(c){const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height)}}}
$("profileCanvas").addEventListener('click',e=>{const r=state.canvasRanges.profile;if(!r)return;const rect=e.currentTarget.getBoundingClientRect(),x=e.clientX-rect.left;state.crossStation=Math.max(0,Math.min(Number(state.analysis?.frame?.length||0),r.map.ix(x)));$("crossStation").value=String(state.crossStation);updateCrossLabel();renderAnalysisViews()});
$("planCanvas").addEventListener('click',e=>{const r=state.canvasRanges.plan;if(!r)return;const rect=e.currentTarget.getBoundingClientRect(),x=e.clientX-rect.left;state.crossStation=Math.max(0,Math.min(Number(state.analysis?.frame?.length||0),r.map.ix(x)));$("crossStation").value=String(state.crossStation);updateCrossLabel();renderAnalysisViews()});
function refreshViewLayout(){
  const grid=document.querySelector('.quad-grid');
  if(!grid)return;
  const cards=[...grid.querySelectorAll('.view-card')];
  grid.classList.toggle('has-maximized',!!state.layout.maximized);
  for(const card of cards){
    const key=card.dataset.view;
    card.classList.toggle('minimized',state.layout.minimized.has(key));
    card.classList.toggle('maximized',state.layout.maximized===key);
    const maxBtn=card.querySelector('[data-action="maximize"]');
    if(maxBtn){maxBtn.textContent=state.layout.maximized===key?'↙':'⛶';maxBtn.title=state.layout.maximized===key?'Restore four-view layout':`Maximize ${card.querySelector('.view-heading b')?.textContent||key}`}
  }
  const visible=cards.filter(c=>!c.classList.contains('minimized')&&(!state.layout.maximized||c.classList.contains('maximized'))).length;
  if(!state.layout.maximized){
    grid.style.gridTemplateColumns=visible<=1?'1fr':'1fr 1fr';
    grid.style.gridTemplateRows=visible<=2?'1fr':'1fr 1fr';
  }else{grid.style.gridTemplateColumns='1fr';grid.style.gridTemplateRows='1fr'}
  const dock=$("viewDock");dock.innerHTML='';
  for(const key of state.layout.minimized){const card=grid.querySelector(`[data-view="${key}"]`);if(!card)continue;const b=document.createElement('button');b.textContent=`Restore ${card.querySelector('.view-heading b')?.textContent||key}`;b.onclick=()=>{state.layout.minimized.delete(key);refreshViewLayout()};dock.appendChild(b)}
  document.querySelector('.workspace')?.classList.toggle('focus-workspace',state.layout.focusWorkspace);
  if($("focusWorkspaceBtn"))$("focusWorkspaceBtn").textContent=state.layout.focusWorkspace?'Restore panels':'Focus workspace';
  requestAnimationFrame(()=>{renderAnalysisViews();const el=$("potree_render_area");state.viewer?.renderer?.setSize?.(el.clientWidth,el.clientHeight)})
}
function toggleMaximize(key){state.layout.maximized=state.layout.maximized===key?null:key;if(state.layout.maximized)state.layout.minimized.delete(key);refreshViewLayout()}
function minimizeView(key){if(state.layout.maximized===key)state.layout.maximized=null;state.layout.minimized.add(key);refreshViewLayout()}
document.querySelectorAll('.view-action').forEach(btn=>btn.onclick=e=>{e.stopPropagation();const key=btn.closest('.view-card')?.dataset.view;if(!key)return;if(btn.dataset.action==='maximize')toggleMaximize(key);else minimizeView(key)});
$("resetLayoutBtn").onclick=()=>{state.layout.maximized=null;state.layout.minimized.clear();state.layout.focusWorkspace=false;refreshViewLayout();toast('Four-view engineering layout restored.','success')};
$("focusWorkspaceBtn").onclick=()=>{state.layout.focusWorkspace=!state.layout.focusWorkspace;refreshViewLayout()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.layout.maximized){state.layout.maximized=null;refreshViewLayout();return}if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;const map={"1":"plan","2":"profile","3":"cross","4":"three"};if(map[e.key])toggleMaximize(map[e.key])});
refreshViewLayout();
window.addEventListener('resize',()=>{renderAnalysisViews();const el=$("potree_render_area");state.viewer?.renderer?.setSize?.(el.clientWidth,el.clientHeight);const production=$("production_render_area");state.productionViewer?.renderer?.setSize?.(production.clientWidth,production.clientHeight)});

// Dynamic dataset upload / processing
$("reprocessBtn").onclick=async()=>{if(!state.projectId)return;const project=currentProject();if(!confirm(`Reprocess ${project.name||state.projectId} using the files already uploaded?\n\nThis will rebuild LiDAR block mapping, delivery geometry and QC findings.`))return;const btn=$("reprocessBtn"),old=btn.textContent;btn.disabled=true;btn.textContent="Reprocessing…";try{const q=await api(`/api/projects/${state.projectId}/process`,{method:"POST"});for(;;){await new Promise(r=>setTimeout(r,1800));const j=await api(`/api/jobs/${q.job_id}`);btn.textContent=`${j.progress}% · ${j.stage}`;if(j.status==="SUCCEEDED")break;if(j.status==="FAILED")throw new Error(j.error||"Reprocessing failed")}await loadProject();if(state.currentPole)await selectPole(state.currentPole.internal_id);toast("Reprocessing complete.","success")}catch(e){toast(e.message,"error",5200)}finally{btn.disabled=false;btn.textContent=old}};
$("newDatasetBtn").onclick=()=>{state.uploadRevisionProjectId=null;$("uploadForm").reset();["datasetName","datasetCustomer","datasetCrs","datasetUnits"].forEach(id=>$(id).disabled=false);$("datasetCustomer").value="PLA";$("datasetCrs").value="EPSG:6424";$("datasetUnits").value="US survey foot";$("uploadDialog").querySelector("h2").textContent="New PLA dataset";$("uploadProgress").classList.add("hidden");$("uploadError").textContent="";$("uploadDialog").showModal()};$("cancelUpload").onclick=()=>{state.uploadRevisionProjectId=null;$("uploadDialog").close()};
function progress(p,msg){$("uploadProgress").classList.remove("hidden");$("uploadBar").style.width=`${Math.max(0,Math.min(100,p))}%`;$("uploadMessage").textContent=msg}
async function sendFile(projectId,file,role,index,total,reporter=progress,preparePath=null){reporter(Math.round((index/total)*55),`Uploading ${file.name} (${index+1}/${total})…`);const prep=await api(preparePath||`/api/projects/${projectId}/uploads/prepare`,{method:"POST",body:JSON.stringify({filename:file.name,role,size_bytes:file.size,content_type:file.type||"application/octet-stream"})});if(prep.mode==="local"){const fd=new FormData();fd.append("file",file,file.name);await api(prep.upload_url,{method:"PUT",body:fd});return prep.file_id}if(prep.mode==="multipart"){const uploaded=[];for(let i=0;i<prep.parts.length;i++){const spec=prep.parts[i],start=i*prep.part_size,end=Math.min(file.size,start+prep.part_size),chunk=file.slice(start,end);reporter(Math.round((index/total)*55+((i+1)/prep.parts.length)*(55/total)),`Uploading ${file.name} · part ${i+1}/${prep.parts.length}`);let response;for(let attempt=1;attempt<=3;attempt++){response=await fetch(spec.url,{method:"PUT",body:chunk});if(response.ok)break;if(attempt===3)throw new Error(`Multipart upload failed: ${file.name}, part ${i+1}`)}const etag=response.headers.get('ETag');if(!etag)throw new Error('Storage did not expose ETag. Check bucket CORS ExposeHeaders: ETag.');uploaded.push({PartNumber:spec.part_number,ETag:etag})}await api(`/api/projects/${projectId}/uploads/${prep.file_id}/multipart-complete`,{method:"POST",body:JSON.stringify({upload_id:prep.upload_id,parts:uploaded})});return prep.file_id}const r=await fetch(prep.upload_url,{method:"PUT",body:file,headers:prep.headers||{}});if(!r.ok)throw new Error(`Storage upload failed for ${file.name}: HTTP ${r.status}`);await api(`/api/projects/${projectId}/uploads/${prep.file_id}/complete`,{method:"POST"});return prep.file_id}
$("uploadForm").onsubmit=async ev=>{ev.preventDefault();$("uploadError").textContent="";try{const revisionProjectId=state.uploadRevisionProjectId;progress(2,revisionProjectId?"Preparing revision…":"Creating dataset…");let project;if(revisionProjectId){project=state.projects.find(p=>p.id===revisionProjectId);if(!project)throw new Error("Revision project is not available")}else{project=await api("/api/projects",{method:"POST",body:JSON.stringify({name:$("datasetName").value.trim(),customer:$("datasetCustomer").value.trim()||"PLA",crs:$("datasetCrs").value.trim(),units:$("datasetUnits").value.trim()})})}const workbook=$("workbookFile").files[0],lidar=[...$("lidarFiles").files];if(!workbook)throw new Error("A COLLECTION workbook is required");if(!revisionProjectId&&!lidar.length)throw new Error("At least one LAS/LAZ/COPC file is required for a new dataset");const files=[workbook,...lidar];for(let i=0;i<files.length;i++)await sendFile(project.id,files[i],i===0?"WORKBOOK":"LIDAR_SOURCE",i,files.length);progress(60,"Queueing LiDAR conversion + QC…");const q=await api(`/api/projects/${project.id}/process`,{method:"POST"});state.projectId=project.id;localStorage.setItem("pla_project_id",project.id);let done=false;while(!done){await new Promise(r=>setTimeout(r,2000));const j=await api(`/api/jobs/${q.job_id}`);progress(60+Math.round(j.progress*.4),`${j.stage} · ${j.progress}%`);if(j.status==="SUCCEEDED")done=true;if(j.status==="FAILED")throw new Error(j.error||"Processing failed")}progress(100,"Ready for QC");await new Promise(r=>setTimeout(r,500));state.uploadRevisionProjectId=null;$("uploadDialog").close();await bootstrap()}catch(e){$("uploadError").textContent=e.message;progress(0,"Processing stopped")}};

function productionProgress(p,msg){$("productionUploadProgress").classList.remove("hidden");$("productionUploadBar").style.width=`${Math.max(0,Math.min(100,p))}%`;$("productionUploadMessage").textContent=msg}
function humanBytes(value){const n=Number(value||0);if(!n)return "0 B";const units=["B","KB","MB","GB","TB"],i=Math.min(units.length-1,Math.floor(Math.log(n)/Math.log(1024)));return `${(n/Math.pow(1024,i)).toFixed(i>1?1:0)} ${units[i]}`}
function humanCount(value){return Number(value||0).toLocaleString()}
function clearProductionMeasurements(){if(!state.productionViewer)return;for(const measure of state.productionMeasurements)state.productionViewer.scene.removeMeasurement(measure);state.productionMeasurements=[]}
function setProductionClipUi(active){$("productionBoxBtn").textContent=active?"Redraw bounding box":"Draw bounding box";$("productionCloseBoxBtn").classList.toggle("hidden",!active)}
function clearProductionClip(refit=true){if(!state.productionViewer)return;state.productionViewer.dispatchEvent({type:"cancel_insertions"});cancelProductionBox();if(state.productionClipVolume)state.productionViewer.scene.removeVolume(state.productionClipVolume);state.productionClipVolume=null;if(!state.productionProfile)state.productionViewer.setClipTask(Potree.ClipTask.NONE);setProductionClipUi(false);if(refit&&state.productionPointclouds.length)state.productionViewer.fitToScreen(.8)}
function clearProductionClouds(){if(!state.productionViewer)return;cancelProductionProfileLine();exitProductionProfile(true);clearProductionClip(false);clearProductionMeasurements();const scene=state.productionViewer.scene;for(const pc of [...(scene.pointclouds||[])]){const i=scene.pointclouds?.indexOf(pc)??-1;if(i>=0)scene.pointclouds.splice(i,1);scene.scenePointCloud?.remove?.(pc);scene.scene?.remove?.(pc);scene.dispatchEvent?.({type:"pointcloud_removed",pointcloud:pc})}state.productionPointclouds=[];state.productionSceneProjectId=null;$("productionBoxBtn").disabled=$("productionProfileBtn").disabled=true}
function combinedProductionBlock(){return {id:"__combined__",name:"__combined__",point_count:state.productionBlocks.reduce((sum,b)=>sum+Number(b.point_count||0),0)}}
function renderProductionContext(files,blocks){const project=currentProject(),points=blocks.reduce((sum,b)=>sum+Number(b.point_count||0),0);$("productionContextTitle").textContent=project.id?project.name:"LiDAR production";$("productionContextMeta").textContent=project.id?`${files.length} LiDAR file${files.length===1?"":"s"} · ${humanCount(points)} points · ${project.crs||""} · ${state.productionPoles.length} pole${state.productionPoles.length===1?"":"s"}`:"Select a project or import LiDAR";$("productionSourceSummary").textContent=`${files.length} file${files.length===1?"":"s"} · ${humanCount(points)} points`}
function renderProduction(){const files=state.productionFiles.filter(f=>f.role==="LIDAR_SOURCE"),blocks=state.productionBlocks;renderProductionContext(files,blocks);{const button=$("productionReplaceExcelBtn"),reason=!(can("upload.create")&&can("processing.run"))?"Your role can't replace the Excel":currentProject().source_project_id?"This is a QC dataset; it uses its own QC Excel":!state.productionFiles.some(f=>f.role==="WORKBOOK"&&f.status==="UPLOADED")?"This dataset has no Production Excel to replace":"";button.disabled=Boolean(reason);button.title=reason||"Uploaded the wrong Excel? Replace it with the correct one"}$("productionFileCount").textContent=files.length;$("productionBlockCount").textContent=blocks.length;$("productionPointCount").textContent=humanCount(blocks.reduce((sum,b)=>sum+Number(b.point_count||0),0));const root=$("productionLidarList");root.innerHTML="";if(!files.length){root.innerHTML='<div class="empty-workflow">No LiDAR files have been uploaded for this project.</div>';return}if(blocks.length){const combined=document.createElement("div");combined.className="lidar-row active";combined.innerHTML=`<div class="lidar-file-icon">ALL</div><span><b>Combined 3D model</b><small>${blocks.length} files · ${humanCount(blocks.reduce((sum,b)=>sum+Number(b.point_count||0),0))} points</small></span><em class="lidar-status">DISPLAYED</em>`;combined.onclick=selectAllProductionBlocks;root.appendChild(combined)}for(const file of files){const block=blocks.find(b=>b.source_filename===file.filename),row=document.createElement("div");row.className=`lidar-row${block?"":" disabled"}`;row.innerHTML=`<div class="lidar-file-icon">${file.filename.toLowerCase().endsWith(".copc.laz")?"COPC":"LAS"}</div><span><b>${esc(file.filename)}</b><small>${humanBytes(file.size_bytes)}${block?.point_count!=null?` · ${humanCount(block.point_count)} points`:""}</small></span><em class="lidar-status">${block?"MERGED":esc(file.status)}</em>`;root.appendChild(row)}const geoFile=[...state.productionFiles].reverse().find(f=>f.role==="GEOJSON");if(geoFile){const g=state.productionGeoFeatures,count=m=>g.filter(f=>f.match_method===m).length,row=document.createElement("div");row.className="lidar-row";row.innerHTML=`<div class="lidar-file-icon">GEO</div><span><b>${esc(geoFile.filename)}</b><small>${g.length?`${humanCount(g.length)} features · ${count("ID")} by ID · ${count("NEAREST")} nearest · ${g.filter(f=>f.geometry_type==="Point"&&!f.match_method).length} unmatched`:"No features imported"}</small></span><em class="lidar-status">SOURCE</em>`;root.appendChild(row)}}
async function downloadProductionAnnotations(){const button=$("productionAnnotationsDownload");button.disabled=true;button.textContent="Preparing…";try{const response=await fetch(`${state.apiBase}/api/projects/${encodeURIComponent(state.projectId)}/production-annotations.geojson`,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok){const text=await response.text();let detail;try{detail=JSON.parse(text)}catch{detail=text}throw new Error(detail?.detail||detail||`HTTP ${response.status}`)}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement("a"),disposition=response.headers.get("Content-Disposition")||"",match=disposition.match(/filename="?([^";]+)"?/i);link.href=url;link.download=match?.[1]||"production-annotation-points.geojson";link.click();setTimeout(()=>URL.revokeObjectURL(url),0);toast(`${state.productionAnnotations.length} saved point${state.productionAnnotations.length===1?"":"s"} exported.`,"success")}catch(error){toast(error.message,"error",5200)}finally{button.textContent="Download GeoJSON";button.disabled=!state.productionAnnotations.length}}
async function loadProduction(){if(!state.projectId)return;const requestedProjectId=state.projectId;try{const [files,blocks,catalogue,annotations,poles,geoFeatures]=await Promise.all([api(`/api/projects/${requestedProjectId}/files`),api(`/api/projects/${requestedProjectId}/lidar-blocks`),api('/api/production/catalogue'),api(`/api/projects/${requestedProjectId}/production-annotations`),api(`/api/projects/${requestedProjectId}/poles`),api(`/api/projects/${requestedProjectId}/production-geo-features`)]);if(requestedProjectId!==state.projectId)return;state.productionFiles=files;state.productionBlocks=blocks;state.productionCatalogue=catalogue;state.productionAnnotations=annotations;state.productionPoles=poles;state.productionGeoFeatures=geoFeatures;closeProductionGeoCard();fillProductionCatalogue();fillProductionPoles();renderProduction();renderProductionAnnotations();renderProductionGeoOverlay();if(blocks.length&&(state.productionSceneProjectId!==requestedProjectId||state.productionPointclouds.length!==blocks.length))await selectAllProductionBlocks()}catch(e){toast(e.message,"error",5200)}}
function loadProductionPointCloud(block,generation,projectId){return new Promise((resolve,reject)=>{Potree.loadPointCloud(block.copc_url,block.name,e=>{try{if(generation!==state.productionLoadGeneration||projectId!==state.projectId){resolve();return}state.productionViewer.scene.addPointCloud(e.pointcloud);e.pointcloud.material.size=1;e.pointcloud.material.pointSizeType=Potree.PointSizeType.ADAPTIVE;e.pointcloud.material.activeAttributeName="elevation";state.productionPointclouds.push(e.pointcloud);resolve()}catch(err){reject(err)}})})}
async function selectAllProductionBlocks(){const blocks=state.productionBlocks;if(!blocks.length)return;const projectId=state.projectId,generation=++state.productionLoadGeneration;state.productionBlock=combinedProductionBlock();state.productionDraft=null;resetAnnotationForm();renderProduction();renderProductionAnnotations();$("productionViewerEmpty").classList.add("hidden");$("productionLoading").classList.remove("hidden");$("productionPickBtn").disabled=!can("production.annotate");$("productionViewerTitle").textContent="Combined LiDAR model";$("productionViewerMeta").textContent=`${blocks.length} files · ${humanCount(state.productionBlock.point_count)} points · ${currentProject().crs}`;try{clearProductionClouds();const results=await Promise.allSettled(blocks.map(block=>loadProductionPointCloud(block,generation,projectId)));if(projectId!==state.projectId||generation!==state.productionLoadGeneration)return;const failures=results.filter(x=>x.status==="rejected");if(state.productionPointclouds.length){state.productionSceneProjectId=projectId;renderProductionAnnotationMarkers();renderProductionChecklist();state.productionViewer.fitToScreen(.8)}if(failures.length)toast(`${failures.length} LiDAR file${failures.length===1?"":"s"} could not be added to the combined view.`,"error",6200);if(!state.productionPointclouds.length)throw new Error("No LiDAR files could be loaded")}catch(e){$("productionViewerEmpty").classList.remove("hidden");$("productionViewerEmpty").innerHTML=`<div class="empty-icon">!</div><h3>LiDAR could not load</h3><p>${esc(e.message)}</p>`}finally{if(generation===state.productionLoadGeneration)$("productionLoading").classList.add("hidden")}}
function productionAnnotationGroups(){return state.productionCatalogue?.annotation_groups||[]}
function fillProductionCatalogue(){const groups=productionAnnotationGroups(),select=$("annotationFamily"),current=select.value;select.innerHTML=groups.map(group=>`<option value="${esc(group.id)}">${esc(group.label)}${group.relationship?` · ${esc(group.relationship)}`:""}</option>`).join("");if(groups.some(group=>group.id===current))select.value=current;fillProductionFeatures()}
function nextProductionFeature(group){const poleId=$("annotationPoleId").value,editing=state.productionAnnotations.find(row=>row.id===$("annotationId").value);if(editing&&editing.family===group.id&&String(editing.pole_internal_id)===poleId)return editing.feature_type;if(!poleId)return null;const expression=new RegExp(`^${group.prefix}_(\\d+)$`,"i"),numbers=state.productionAnnotations.filter(row=>row.family===group.id&&String(row.pole_internal_id)===poleId).map(row=>expression.exec(row.feature_type)?.[1]).filter(Boolean).map(Number),next=Math.max(0,...numbers)+1;return `${group.prefix}_${next}`}
function fillProductionFeatures(){const group=productionAnnotationGroups().find(item=>item.id===$("annotationFamily").value),select=$("annotationFeature"),current=select.value;if(!group){select.replaceChildren();return}if(group.automatic_numbering){const next=nextProductionFeature(group),message=next?`${next} · assigned automatically`:`Select a Pole Number first`;select.replaceChildren(new Option(message,next||""));select.dataset.automatic="true"}else{delete select.dataset.automatic;select.innerHTML=(group.point_types||[]).map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join("");if((group.point_types||[]).includes(current))select.value=current}}
$("annotationFamily").onchange=fillProductionFeatures;
function coordinateText(latitude,longitude){return latitude!=null&&longitude!=null&&Number.isFinite(Number(latitude))&&Number.isFinite(Number(longitude))?`${Number(latitude).toFixed(8)}, ${Number(longitude).toFixed(8)}`:"—"}
function updateStreetViewButton(){const point=state.productionDraftGeographic,valid=point&&Number.isFinite(Number(point.latitude))&&Number.isFinite(Number(point.longitude));$("annotationStreetView").disabled=!valid}
function openAnnotationStreetView(){const point=state.productionDraftGeographic,latitude=Number(point?.latitude),longitude=Number(point?.longitude);if(!Number.isFinite(latitude)||!Number.isFinite(longitude))return;const viewpoint=encodeURIComponent(`${latitude},${longitude}`);window.open(`https://www.google.com/maps/@?api=1&map_action=pano&viewpoint=${viewpoint}`,"_blank","noopener,noreferrer")}
function elevationText(value){return value==null||!Number.isFinite(Number(value))?"—":`${Number(value).toFixed(3)} ${annotationUnits()}`}
function updatePoleCoordinateComparison(){const pole=state.productionPoles.find(x=>String(x.internal_id)===$("annotationPoleId").value),root=document.querySelector(".pole-coordinate-comparison");if(!root)return;root.innerHTML=`<span>Verified pole location<b>${pole?coordinateText(pole.verified_latitude,pole.verified_longitude):"—"}</b></span><span>LiDAR bottom elevation<b>${pole?elevationText(pole.verified_bottom_elevation):"—"}</b></span><span>LiDAR top elevation<b>${pole?elevationText(pole.verified_top_elevation):"—"}</b></span><span>Calculated pole height<b>${pole?elevationText(pole.verified_height):"—"}</b></span>`}
function fillProductionPoles(selected=null){const select=$("annotationPoleId"),current=selected??select.value;select.innerHTML='<option value="">Select a workbook pole</option>'+state.productionPoles.map(p=>`<option value="${p.internal_id}">${esc(p.pole_number||`Pole ${p.internal_id}`)} · ID ${p.internal_id}${p.verified_latitude!=null?" · VERIFIED":""}</option>`).join("");if(state.productionPoles.some(p=>String(p.internal_id)===String(current)))select.value=String(current);updatePoleCoordinateComparison()}
$("annotationPoleId").onchange=()=>{const poleId=$("annotationPoleId").value,family=$("annotationFamily").value,editing=state.productionAnnotations.find(row=>row.id===$("annotationId").value);if(editing&&String(editing.pole_internal_id)!==poleId){resetAnnotationForm({poleId,family});renderProductionAnnotations();return}updatePoleCoordinateComparison();fillProductionFeatures();renderProductionAnnotations()};
function annotationUnits(){return currentProject().units||"project units"}
function resetAnnotationForm({poleId="",family=""}={}){state.productionDraft=null;state.productionDraftGeographic=null;$("annotationForm").reset();$("annotationId").value="";$("annotationX").textContent=$("annotationY").textContent=$("annotationZ").textContent=$("annotationLat").textContent=$("annotationLon").textContent="—";$("annotationMode").textContent=poleId?"Pick a point from the checklist":"Choose a pole, then pick its points";document.querySelectorAll("#annotationForm .coordinate-readout,#annotationForm .geographic-readout").forEach(el=>el.classList.add("hidden"));$("annotationError").textContent="";$("annotationDeleteBtn").classList.add("hidden");$("annotationSaveBtn").disabled=true;updateStreetViewButton();fillProductionCatalogue();if(productionAnnotationGroups().some(group=>group.id===family))$("annotationFamily").value=family;fillProductionPoles(poleId);fillProductionFeatures()}
async function updateDraftGeographic(){const draft=state.productionDraft;if(!draft||!state.projectId)return;const key=`${draft.x}|${draft.y}|${draft.z}`;$("annotationLat").textContent=$("annotationLon").textContent="Calculating…";try{const result=await api(`/api/projects/${state.projectId}/coordinates/to-wgs84`,{method:"POST",body:JSON.stringify(draft)});if(!state.productionDraft||`${state.productionDraft.x}|${state.productionDraft.y}|${state.productionDraft.z}`!==key)return;state.productionDraftGeographic=result;$("annotationLat").textContent=Number(result.latitude).toFixed(8);$("annotationLon").textContent=Number(result.longitude).toFixed(8);updateStreetViewButton()}catch(e){state.productionDraftGeographic=null;$("annotationLat").textContent=$("annotationLon").textContent="Unavailable";$("annotationError").textContent=e.message;updateStreetViewButton()}}
function setAnnotationDraft(coords,annotation=null){state.productionDraft={x:Number(coords.x),y:Number(coords.y),z:Number(coords.z)};document.querySelectorAll("#annotationForm .coordinate-readout,#annotationForm .geographic-readout").forEach(el=>el.classList.remove("hidden"));state.productionDraftGeographic=annotation?.geographic_coordinates||null;$("annotationX").textContent=state.productionDraft.x.toFixed(3);$("annotationY").textContent=state.productionDraft.y.toFixed(3);$("annotationZ").textContent=state.productionDraft.z.toFixed(3);$("annotationLat").textContent=annotation?.geographic_coordinates?.latitude!=null?Number(annotation.geographic_coordinates.latitude).toFixed(8):"Calculating…";$("annotationLon").textContent=annotation?.geographic_coordinates?.longitude!=null?Number(annotation.geographic_coordinates.longitude).toFixed(8):"Calculating…";$("annotationMode").textContent=annotation?"Editing saved point":"New point selected";$("annotationSaveBtn").disabled=!can("production.annotate");updateStreetViewButton();renderProductionAnnotationMarkers();updateDraftGeographic()}
function addProductionMeasurement(points,{name="Production point",color=0xffd65a,distances=false,height=false,coordinates=false}={}){if(!state.productionViewer||!points.length)return;const projectUnits=annotationUnits().toLowerCase();state.productionViewer.setLengthUnit(projectUnits.includes("foot")||projectUnits.includes("feet")?"ft":"m");const measure=new Potree.Measure();measure.name=name;measure.color=new THREE.Color(color);measure.closed=false;measure.showDistances=distances;measure.showHeight=height;measure.showCoordinates=coordinates;measure.showEdges=points.length>1;measure.maxMarkers=points.length;measure.lengthUnit=state.productionViewer.lengthUnit;measure.lengthUnitDisplay=state.productionViewer.lengthUnitDisplay;for(const point of points)measure.addMarker(new THREE.Vector3(Number(point.x),Number(point.y),Number(point.z)));for(const edge of measure.edges)edge.material.color.set(color);for(const sphere of measure.spheres)sphere._listeners={};state.productionViewer.scene.addMeasurement(measure);state.productionMeasurements.push(measure)}
const productionAnnotationColors={crossarms:0xffa45b,attachments_comm:0x53d9ff,attachments_util:0x7ed6ff,anchors:0xff6262,guys:0xff65d8,sidewalk_braces:0xd49cff,equipment:0xffca5b,span_guys:0xa9e36b,poles:0xffe066,other_poles:0xf3a6ff,"Pole Points":0xffe066};
function selectedPoleAnnotations(){const poleId=$("annotationPoleId").value;return poleId?state.productionAnnotations.filter(row=>String(row.pole_internal_id??row.attributes?.pole_internal_id)===poleId):[]}
function renderProductionAnnotationMarkers(){clearProductionMeasurements();if(!state.productionViewer)return;$("productionBoxBtn").disabled=$("productionProfileBtn").disabled=!state.productionPointclouds.length;const activeId=$("annotationId").value,rows=$("annotationPoleId").value?selectedPoleAnnotations():state.productionAnnotations;for(const row of rows){if(row.id===activeId&&state.productionDraft)continue;addProductionMeasurement([row.coordinates],{name:row.feature_type,color:productionAnnotationColors[row.family]||0xffffff})}if(state.productionDraft)addProductionMeasurement([state.productionDraft],{name:$("annotationFeature").value||"Unsaved point",color:productionAnnotationColors[$("annotationFamily").value]||0xffffff,coordinates:true})}
function renderProductionAnnotations(){const root=$("productionAnnotationList"),poleId=$("annotationPoleId").value,rows=selectedPoleAnnotations();$("productionAnnotationsDownload").disabled=!state.productionAnnotations.length;root.innerHTML="";renderProductionPoleWorkflow();if(!poleId){root.innerHTML='<div class="empty-workflow">Select a Pole Number to view its saved points.</div>';renderProductionAnnotationMarkers();return}if(!rows.length){root.innerHTML='<div class="empty-workflow">No points saved for this pole.</div>';renderProductionAnnotationMarkers();return}for(const row of rows){const pole=state.productionPoles.find(item=>item.internal_id===row.pole_internal_id),item=document.createElement("div");item.className=`annotation-row${$("annotationId").value===row.id?" active":""}`;item.innerHTML=`<b><i class="annotation-dot"></i>${esc(row.feature_type)}</b><small>${esc(pole?.pole_number||`Pole ID ${row.pole_internal_id||"—"}`)} · ${esc(row.family)} · Z ${Number(row.coordinates.z).toFixed(3)}</small>`;item.onclick=()=>editProductionAnnotation(row);root.appendChild(item)}renderProductionAnnotationMarkers()}
// Pole-by-pole workflow: the single pole selection (#annotationPoleId) drives the list, header, checklist, 3D view and workbook tab.
const productionGroupLabels={crossarms:"Crossarms",attachments_comm:"Comm attachments",attachments_util:"Utility attachments",anchors:"Anchors",guys:"Guys",sidewalk_braces:"Sidewalk braces",equipment:"Equipment",span_guys:"Span guys",other_poles:"Other poles"};
function isPoleBase(row){return row.feature_type==="Pole_Base"||row.feature_type==="Pole Base / Ground Point"}
function isPoleTop(row){return row.feature_type==="Pole_Top"||row.feature_type==="Pole Top Point"}
function productionPoleStatus(pole){const rows=state.productionAnnotations.filter(row=>String(row.pole_internal_id??row.attributes?.pole_internal_id)===String(pole.internal_id)),base=rows.find(isPoleBase),top=rows.find(isPoleTop);return {rows,base,top,state:base&&top?"done":rows.length?"progress":"todo"}}
function productionGeoForPole(pole){return state.productionGeoFeatures.find(f=>f.geometry_type==="Point"&&f.pole_internal_id===pole.internal_id)}
function visibleProductionPoles(){const query=state.productionPoleQuery.trim().toLowerCase(),filter=state.productionPoleFilter;return state.productionPoles.filter(pole=>{if(query&&!`${pole.pole_number||""} ${pole.internal_id}`.toLowerCase().includes(query))return false;const status=productionPoleStatus(pole).state;return filter==="all"||(filter==="done"?status==="done":status!=="done")})}
function renderProductionPoleList(){const root=$("productionPoleList"),poles=visibleProductionPoles(),selected=$("annotationPoleId").value,total=state.productionPoles.length,done=state.productionPoles.filter(p=>productionPoleStatus(p).state==="done").length,labels={todo:"To do",progress:"In progress",done:"Done"};$("productionPoleProgress").textContent=total?`${done} / ${total} done`:"—";root.innerHTML="";root.appendChild(productionFullModelRow(!selected));if(!total){root.insertAdjacentHTML("beforeend",'<div class="empty-workflow">No workbook poles in this project.</div>');return}if(!poles.length){root.insertAdjacentHTML("beforeend",'<div class="empty-workflow">No poles match.</div>');return}for(const pole of poles){const status=productionPoleStatus(pole),geo=productionGeoForPole(pole),row=document.createElement("button");row.type="button";row.className=`production-pole-row status-${status.state}${String(pole.internal_id)===selected?" active":""}`;row.dataset.pole=pole.internal_id;row.innerHTML=`<span class="pole-row-name"><b>${esc(pole.pole_number||`Pole ${pole.internal_id}`)}</b><small>${status.rows.length} point${status.rows.length===1?"":"s"}${geo?" · GeoJSON":""}</small></span><span class="pole-chips"><i class="${status.base?"ok":""}" title="Pole base ${status.base?"picked":"not picked"}">B</i><i class="${status.top?"ok":""}" title="Pole top ${status.top?"picked":"not picked"}">T</i></span><em>${labels[status.state]}</em>`;row.onclick=()=>selectProductionPole(pole.internal_id);root.appendChild(row)}root.querySelector(".production-pole-row.active")?.scrollIntoView({block:"nearest"})}
