$("cancelProductionUpload").onclick=()=>$("productionUploadDialog").close();
// Replace a wrongly imported Production Excel: upload, retire the old Excel, re-import poles (LiDAR is reused).
$("productionReplaceExcelBtn").onclick=()=>{$("replaceExcelForm").reset();$("replaceExcelDataset").textContent=currentProject().name||"this dataset";$("replaceExcelProgress").classList.add("hidden");$("replaceExcelError").textContent="";$("replaceExcelDialog").showModal()};
$("cancelReplaceExcel").onclick=()=>$("replaceExcelDialog").close();
$("replaceExcelForm").onsubmit=async ev=>{ev.preventDefault();$("replaceExcelError").textContent="";const report=(p,m)=>setDialogProgress("replaceExcel",p,m),projectId=state.projectId;try{const file=$("replaceExcelFile").files[0];if(!file)throw new Error("Select the correct Excel");const fileId=await sendFile(projectId,file,"WORKBOOK",0,1,report,`/api/projects/${projectId}/production-workbook/prepare`);report(60,"Re-importing poles from the new Excel…");const applied=await api(`/api/projects/${projectId}/production-workbook/${fileId}/apply`,{method:"POST"});let job;for(;;){await new Promise(r=>setTimeout(r,1500));job=await api(`/api/jobs/${applied.job_id}`);report(60+Math.round(job.progress*.4),`${job.stage} · ${job.progress}%`);if(job.status==="SUCCEEDED")break;if(job.status==="FAILED")throw new Error((job.error||"Excel replacement failed").split("\n")[0])}report(100,"Excel replaced");$("replaceExcelDialog").close();if(state.projectId===projectId)await loadProduction();toast(job.message||"Excel replaced and poles re-imported.","success",9000)}catch(e){$("replaceExcelError").textContent=e.message;report(0,"Replacement stopped")}};
$("productionUploadForm").onsubmit=async ev=>{ev.preventDefault();$("productionUploadError").textContent="";try{const workbook=$("productionWorkbookFile").files[0],geojson=$("productionGeojsonFile").files[0],lidar=[...$("productionLidarFiles").files];if(!workbook)throw new Error("Select the client pole workbook");if(!lidar.length)throw new Error("Select at least one LAS, LAZ, or COPC file");if(geojson)await checkGeojsonFile(geojson);const uploads=[{file:workbook,role:"WORKBOOK"},...(geojson?[{file:geojson,role:"GEOJSON"}]:[]),...lidar.map(file=>({file,role:"LIDAR_SOURCE"}))];productionProgress(2,"Creating production dataset…");const project=await api("/api/projects",{method:"POST",body:JSON.stringify({name:$("productionDatasetName").value.trim(),customer:$("productionCustomer").value.trim()||"PLA",crs:$("productionCrs").value.trim(),units:$("productionUnits").value.trim()})});for(let i=0;i<uploads.length;i++)await sendFile(project.id,uploads[i].file,uploads[i].role,i,uploads.length,productionProgress);productionProgress(60,geojson?"Queueing LiDAR conversion, pole and GeoJSON import…":"Queueing LiDAR conversion and pole import…");const queued=await api(`/api/projects/${project.id}/process-lidar`,{method:"POST"});state.projectId=project.id;localStorage.setItem("pla_project_id",project.id);let finished=null;for(;;){await new Promise(r=>setTimeout(r,1800));const job=await api(`/api/jobs/${queued.job_id}`);productionProgress(60+Math.round(job.progress*.4),`${job.stage} · ${job.progress}%`);if(job.status==="SUCCEEDED"){finished=job;break}if(job.status==="FAILED")throw new Error(job.error||"Production processing failed")}productionProgress(100,"LiDAR and pole catalogue ready");await new Promise(r=>setTimeout(r,400));$("productionUploadDialog").close();await bootstrap();toast(`${lidar.length} LiDAR file${lidar.length===1?"":"s"} and workbook ready.`,"success");if(finished?.message?.startsWith("GeoJSON"))toast(finished.message,finished.message.startsWith("GeoJSON rejected")?"error":"info",9000)}catch(e){$("productionUploadError").textContent=e.message;productionProgress(0,"Import stopped")}};
// Fail fast in the browser on an unusable GeoJSON before any multi-GB LiDAR is uploaded; the server validates again.
async function checkGeojsonFile(file){if(file.size>50*1024*1024)throw new Error("GeoJSON exceeds the 50 MB limit");let geo;try{geo=JSON.parse(await file.text())}catch{throw new Error(`${file.name} is not valid JSON`)}const features=geo?.type==="FeatureCollection"&&Array.isArray(geo.features)?geo.features:geo?.type==="Feature"?[geo]:null;if(!features)throw new Error(`${file.name} is not a GeoJSON FeatureCollection`);if(!features.some(f=>f?.geometry))throw new Error(`${file.name} contains no located features`)}

(async function(){if(state.token&&state.apiBase){try{await api('/api/auth/me');showApp();await bootstrap();return}catch{}}showLogin()})();
